[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --teal: #02838D;
      --teal-dark: #026b74;
      --teal-light: #e6f5f6;
      --teal-muted: #a8dce0;
      --charcoal: #231F20;
      --white: #FFFFFF;
      --gray-50: #FAFBFB;
      --gray-100: #F3F5F6;
      --gray-200: #E8ECED;
      --gray-300: #D1D7D9;
      --gray-400: #9BA5A8;
      --gray-500: #6B7578;
      --gray-600: #4A5254;
      --coral: #E8734A;
      --coral-dark: #D4623B;
      --amber: #F5A623;
      --amber-light: #FFF8ED;
      --green-light: #E8F5E9;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
      --transition: 0.2s ease;
      --max-width: 1200px;
    }

    body {
      font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { max-width: 100%; display: block; }
    ul { list-style: none; }

    .container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

    /* ============ HEADER ============ */
    .header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 1000;
    }

    .header-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 24px;
      max-width: var(--max-width);
      margin: 0 auto;
    }

    .logo {
      font-size: 26px;
      font-weight: 700;
      color: var(--teal);
      letter-spacing: -0.5px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--teal);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 20px; height: 20px; fill: var(--white); }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 20px;
    }

    .header-actions a {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-500);
      transition: color var(--transition);
    }

    .header-actions a:hover { color: var(--teal); }

    .btn-subscribe {
      padding: 8px 20px;
      background: var(--teal);
      color: var(--white) !important;
      border-radius: 100px;
      font-size: 14px;
      font-weight: 600;
      transition: background var(--transition);
    }

    .btn-subscribe:hover { background: var(--teal-dark); }

    /* Main Navigation */
    .main-nav {
      background: var(--white);
      border-top: 1px solid var(--gray-200);
    }

    .nav-list {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0;
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    .nav-item {
      position: relative;
    }

    .nav-item > button {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 14px 20px;
      font-size: 15px;
      font-weight: 500;
      color: var(--charcoal);
      transition: color var(--transition);
    }

    .nav-item > button:hover { color: var(--teal); }

    .nav-item > button svg {
      width: 12px;
      height: 12px;
      transition: transform var(--transition);
    }

    .nav-item.open > button { color: var(--teal); }
    .nav-item.open > button svg { transform: rotate(180deg); }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      padding: 24px 28px;
      min-width: 480px;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.2s, visibility 0.2s;
      z-index: 100;
    }

    .nav-item.open .mega-menu {
      opacity: 1;
      visibility: visible;
    }

    .mega-menu h4 {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--gray-400);
      margin-bottom: 12px;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 8px 32px;
    }

    .mega-menu-grid a {
      font-size: 14px;
      padding: 6px 0;
      color: var(--charcoal);
      transition: color var(--transition);
      white-space: nowrap;
    }

    .mega-menu-grid a:hover { color: var(--teal); }

    .mega-menu-section + .mega-menu-section {
      margin-top: 20px;
      padding-top: 20px;
      border-top: 1px solid var(--gray-200);
    }

    /* ============ CREDIBILITY TICKER ============ */
    .ticker-bar {
      background: var(--teal);
      color: var(--white);
      overflow: hidden;
      position: relative;
      padding: 10px 0;
    }

    .ticker-track {
      display: flex;
      animation: ticker-scroll 30s linear infinite;
      width: max-content;
    }

    .ticker-track:hover { animation-play-state: paused; }

    .ticker-item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0 40px;
      font-size: 14px;
      font-weight: 500;
      white-space: nowrap;
    }

    .ticker-item svg { width: 16px; height: 16px; fill: currentColor; flex-shrink: 0; opacity: 0.8; }

    .ticker-separator {
      width: 4px;
      height: 4px;
      background: rgba(255,255,255,0.4);
      border-radius: 50%;
      flex-shrink: 0;
    }

    @keyframes ticker-scroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* ============ HERO ============ */
    .hero {
      padding: 48px 0;
      background: var(--gray-50);
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1fr 380px;
      gap: 40px;
      align-items: start;
    }

    .hero-main {
      background: linear-gradient(135deg, #e6f5f6 0%, #d4eef0 50%, #c2e7ea 100%);
      border-radius: var(--radius-lg);
      padding: 48px;
      position: relative;
      overflow: hidden;
      min-height: 380px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
    }

    .hero-badge {
      position: absolute;
      top: 24px;
      right: 24px;
      background: var(--coral);
      color: var(--white);
      padding: 10px 16px;
      border-radius: var(--radius-sm);
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      line-height: 1.3;
      text-align: center;
    }

    .hero-badge span { display: block; font-size: 18px; }

    .hero-category {
      display: inline-block;
      background: var(--teal);
      color: var(--white);
      padding: 4px 12px;
      border-radius: 100px;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 16px;
    }

    .hero-title {
      font-size: 32px;
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 12px;
      color: var(--charcoal);
    }

    .hero-subtitle {
      font-size: 16px;
      color: var(--gray-600);
      line-height: 1.5;
      max-width: 500px;
    }

    /* Trending sidebar */
    .trending-sidebar {
      background: var(--white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--gray-200);
      overflow: hidden;
    }

    .trending-header {
      padding: 20px 24px;
      border-bottom: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .trending-header h3 {
      font-size: 16px;
      font-weight: 700;
    }

    .trending-header svg { color: var(--coral); width: 18px; height: 18px; }

    .trending-list { padding: 8px 0; }

    .trending-item {
      display: flex;
      gap: 16px;
      padding: 16px 24px;
      transition: background var(--transition);
      cursor: pointer;
    }

    .trending-item:hover { background: var(--gray-50); }

    .trending-number {
      font-size: 28px;
      font-weight: 700;
      color: var(--gray-300);
      line-height: 1;
      min-width: 30px;
    }

    .trending-content { flex: 1; }

    .trending-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--teal);
      margin-bottom: 4px;
    }

    .trending-title {
      font-size: 14px;
      font-weight: 600;
      line-height: 1.4;
    }

    /* ============ NEWSLETTER CTA ============ */
    .newsletter-cta {
      padding: 64px 0;
      background: linear-gradient(135deg, var(--teal) 0%, var(--teal-dark) 100%);
      color: var(--white);
      text-align: center;
    }

    .newsletter-inner {
      max-width: 560px;
      margin: 0 auto;
    }

    .newsletter-icon {
      width: 56px;
      height: 56px;
      background: rgba(255,255,255,0.15);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
    }

    .newsletter-icon svg { width: 28px; height: 28px; fill: var(--white); }

    .newsletter-cta h2 {
      font-size: 30px;
      font-weight: 700;
      margin-bottom: 12px;
    }

    .newsletter-cta p {
      font-size: 16px;
      opacity: 0.9;
      margin-bottom: 28px;
      line-height: 1.6;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 460px;
      margin: 0 auto 12px;
    }

    .newsletter-form input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid rgba(255,255,255,0.3);
      border-radius: 100px;
      background: rgba(255,255,255,0.1);
      color: var(--white);
      font-size: 15px;
      font-family: inherit;
      outline: none;
      transition: border-color var(--transition);
    }

    .newsletter-form input::placeholder { color: rgba(255,255,255,0.6); }
    .newsletter-form input:focus { border-color: rgba(255,255,255,0.7); }

    .newsletter-form button {
      padding: 14px 32px;
      background: var(--coral);
      color: var(--white);
      border-radius: 100px;
      font-size: 15px;
      font-weight: 700;
      transition: background var(--transition);
      white-space: nowrap;
    }

    .newsletter-form button:hover { background: var(--coral-dark); }

    .newsletter-privacy {
      font-size: 13px;
      opacity: 0.7;
    }

    .newsletter-privacy svg {
      width: 12px;
      height: 12px;
      display: inline;
      vertical-align: middle;
      margin-right: 4px;
    }

    /* ============ HEALTH TOPICS ============ */
    .health-topics {
      padding: 64px 0;
      background: var(--white);
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }

    .section-header h2 {
      font-size: 26px;
      font-weight: 700;
    }

    .view-all {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      transition: gap var(--transition);
    }

    .view-all:hover { gap: 10px; }
    .view-all svg { width: 14px; height: 14px; }

    .topics-carousel-wrapper {
      position: relative;
    }

    .topics-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 8px 0;
    }

    .topics-carousel::-webkit-scrollbar { display: none; }

    .topic-card {
      flex: 0 0 160px;
      text-align: center;
      cursor: pointer;
      transition: transform var(--transition);
    }

    .topic-card:hover { transform: translateY(-4px); }

    .topic-image {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      margin: 0 auto 12px;
      overflow: hidden;
      border: 3px solid var(--gray-200);
      transition: border-color var(--transition);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
    }

    .topic-card:hover .topic-image { border-color: var(--teal); }

    .topic-image-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
    }

    .topic-card h3 {
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-70%);
      width: 40px;
      height: 40px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      z-index: 2;
      transition: all var(--transition);
    }

    .carousel-btn:hover {
      background: var(--teal);
      border-color: var(--teal);
      color: var(--white);
    }

    .carousel-btn svg { width: 16px; height: 16px; }
    .carousel-btn.prev { left: -20px; }
    .carousel-btn.next { right: -20px; }

    /* topic color backgrounds */
    .topic-bg-1 { background: linear-gradient(135deg, #e8d5e8, #f0e0f0); }
    .topic-bg-2 { background: linear-gradient(135deg, #d5e8d5, #e0f0e0); }
    .topic-bg-3 { background: linear-gradient(135deg, #ffd5d5, #ffe0e0); }
    .topic-bg-4 { background: linear-gradient(135deg, #d5d5e8, #e0e0f0); }
    .topic-bg-5 { background: linear-gradient(135deg, #d5e8e8, #e0f0f0); }
    .topic-bg-6 { background: linear-gradient(135deg, #e8e8d5, #f0f0e0); }

    /* ============ HEALTH TOOLS ============ */
    .health-tools {
      padding: 64px 0;
      background: var(--gray-50);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }

    .tool-hub {
      background: var(--white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--gray-200);
      overflow: hidden;
    }

    .tool-hub-header {
      padding: 32px 28px 24px;
      background: linear-gradient(135deg, var(--teal-light), #d4eef0);
    }

    .tool-hub-header h3 {
      font-size: 22px;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .tool-hub-header p {
      font-size: 14px;
      color: var(--gray-600);
      line-height: 1.5;
      margin-bottom: 16px;
    }

    .btn-teal {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 10px 20px;
      background: var(--teal);
      color: var(--white);
      border-radius: 100px;
      font-size: 14px;
      font-weight: 600;
      transition: background var(--transition);
    }

    .btn-teal:hover { background: var(--teal-dark); }
    .btn-teal svg { width: 14px; height: 14px; }

    .tool-list { padding: 8px 0; }

    .tool-item {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 16px 28px;
      transition: background var(--transition);
      cursor: pointer;
    }

    .tool-item:hover { background: var(--gray-50); }

    .tool-icon {
      width: 44px;
      height: 44px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 20px;
    }

    .tool-icon-green { background: var(--green-light); }
    .tool-icon-amber { background: var(--amber-light); }
    .tool-icon-teal { background: var(--teal-light); }

    .tool-item-content h4 {
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 2px;
    }

    .tool-item-content p {
      font-size: 13px;
      color: var(--gray-500);
      line-height: 1.4;
    }

    /* Drug & Care section */
    .drug-tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      padding: 24px;
    }

    .drug-tool-card {
      padding: 20px;
      background: var(--gray-50);
      border-radius: var(--radius-md);
      transition: all var(--transition);
      cursor: pointer;
    }

    .drug-tool-card:hover {
      background: var(--white);
      box-shadow: var(--shadow-md);
    }

    .drug-tool-card .tool-icon {
      margin-bottom: 12px;
    }

    .drug-tool-card h4 {
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 6px;
    }

    .drug-tool-card p {
      font-size: 13px;
      color: var(--gray-500);
      line-height: 1.4;
    }

    .drug-tool-card .tool-cta {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
      margin-top: 8px;
    }

    .drug-tool-card .tool-cta svg { width: 12px; height: 12px; }

    /* ============ RECOMMENDED READS ============ */
    .recommended-reads {
      padding: 64px 0;
      background: var(--white);
    }

    .tabs-bar {
      display: flex;
      gap: 4px;
      margin-bottom: 32px;
      border-bottom: 2px solid var(--gray-200);
      overflow-x: auto;
      scrollbar-width: none;
    }

    .tabs-bar::-webkit-scrollbar { display: none; }

    .tab-btn {
      padding: 12px 20px;
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-500);
      border-bottom: 2px solid transparent;
      margin-bottom: -2px;
      transition: all var(--transition);
      white-space: nowrap;
    }

    .tab-btn:hover { color: var(--charcoal); }

    .tab-btn.active {
      color: var(--teal);
      border-bottom-color: var(--teal);
      font-weight: 600;
    }

    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .read-card {
      background: var(--white);
      border-radius: var(--radius-md);
      border: 1px solid var(--gray-200);
      overflow: hidden;
      transition: all var(--transition);
      cursor: pointer;
    }

    .read-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .read-card-img {
      height: 180px;
      overflow: hidden;
    }

    .read-card-img-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
    }

    .read-card-body { padding: 20px; }

    .read-card-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--teal);
      margin-bottom: 8px;
    }

    .read-card-body h3 {
      font-size: 16px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 8px;
    }

    .read-card-meta {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 13px;
      color: var(--gray-400);
    }

    .tab-content { display: none; }
    .tab-content.active { display: block; }

    /* ============ TRUST SECTION ============ */
    .trust-section {
      padding: 80px 0;
      background: var(--gray-50);
    }

    .trust-section h2 {
      font-size: 30px;
      font-weight: 700;
      text-align: center;
      margin-bottom: 48px;
    }

    .trust-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .trust-card {
      text-align: center;
      padding: 32px 24px;
      background: var(--white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--gray-200);
      transition: all var(--transition);
    }

    .trust-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .trust-icon {
      width: 64px;
      height: 64px;
      border-radius: 50%;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
    }

    .trust-icon svg { width: 28px; height: 28px; fill: var(--teal); }

    .trust-card h3 {
      font-size: 17px;
      font-weight: 700;
      margin-bottom: 10px;
    }

    .trust-card p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* ============ FEATURED PROGRAMS ============ */
    .featured-programs {
      padding: 64px 0;
      background: var(--white);
    }

    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .program-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      transition: all var(--transition);
      cursor: pointer;
    }

    .program-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .program-card-img {
      height: 140px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 36px;
    }

    .program-card-body {
      padding: 16px;
    }

    .program-card-body h3 {
      font-size: 14px;
      font-weight: 600;
      line-height: 1.4;
    }

    .prog-bg-1 { background: linear-gradient(135deg, #fce4ec, #f8bbd0); }
    .prog-bg-2 { background: linear-gradient(135deg, #e8eaf6, #c5cae9); }
    .prog-bg-3 { background: linear-gradient(135deg, #e0f2f1, #b2dfdb); }
    .prog-bg-4 { background: linear-gradient(135deg, #e3f2fd, #bbdefb); }

    /* ============ LATEST VIDEOS ============ */
    .latest-videos {
      padding: 64px 0;
      background: var(--gray-50);
    }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .video-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      background: var(--white);
      border: 1px solid var(--gray-200);
      transition: all var(--transition);
      cursor: pointer;
    }

    .video-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .video-thumb {
      position: relative;
      height: 140px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 36px;
    }

    .play-btn {
      position: absolute;
      width: 48px;
      height: 48px;
      background: rgba(255,255,255,0.9);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      transition: all var(--transition);
    }

    .video-card:hover .play-btn {
      background: var(--coral);
    }

    .play-btn svg { width: 20px; height: 20px; fill: var(--charcoal); }
    .video-card:hover .play-btn svg { fill: var(--white); }

    .video-card-body { padding: 16px; }

    .video-card-body h3 {
      font-size: 14px;
      font-weight: 600;
      line-height: 1.4;
    }

    .vid-bg-1 { background: linear-gradient(135deg, #e8f5e9, #c8e6c9); }
    .vid-bg-2 { background: linear-gradient(135deg, #fff3e0, #ffe0b2); }
    .vid-bg-3 { background: linear-gradient(135deg, #e3f2fd, #bbdefb); }
    .vid-bg-4 { background: linear-gradient(135deg, #fce4ec, #f8bbd0); }

    /* ============ FOOTER ============ */
    .footer {
      background: var(--charcoal);
      color: var(--white);
      padding: 64px 0 0;
    }

    .footer-newsletter {
      max-width: 560px;
      margin: 0 auto;
      text-align: center;
      padding-bottom: 48px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .footer-newsletter h3 {
      font-size: 22px;
      font-weight: 700;
      margin-bottom: 12px;
    }

    .footer-newsletter p {
      font-size: 14px;
      opacity: 0.7;
      line-height: 1.6;
      margin-bottom: 24px;
    }

    .footer-newsletter-form {
      display: flex;
      gap: 12px;
    }

    .footer-newsletter-form input {
      flex: 1;
      padding: 12px 20px;
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 100px;
      background: rgba(255,255,255,0.08);
      color: var(--white);
      font-size: 14px;
      font-family: inherit;
      outline: none;
      transition: border-color var(--transition);
    }

    .footer-newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
    .footer-newsletter-form input:focus { border-color: rgba(255,255,255,0.5); }

    .footer-newsletter-form button {
      padding: 12px 28px;
      background: var(--teal);
      color: var(--white);
      border-radius: 100px;
      font-size: 14px;
      font-weight: 600;
      transition: background var(--transition);
    }

    .footer-newsletter-form button:hover { background: var(--teal-dark); }

    .footer-links {
      padding: 32px 0;
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 24px;
    }

    .footer-links a {
      font-size: 13px;
      opacity: 0.6;
      transition: opacity var(--transition);
    }

    .footer-links a:hover { opacity: 1; }

    .footer-social {
      display: flex;
      justify-content: center;
      gap: 20px;
      padding: 24px 0;
      border-top: 1px solid rgba(255,255,255,0.1);
    }

    .footer-social a {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition);
    }

    .footer-social a:hover { background: var(--teal); }
    .footer-social a svg { width: 16px; height: 16px; fill: var(--white); }

    .footer-legal {
      text-align: center;
      padding: 24px 0;
      font-size: 12px;
      opacity: 0.5;
      line-height: 1.6;
      border-top: 1px solid rgba(255,255,255,0.05);
    }

    /* ============ RESPONSIVE ============ */
    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; }
      .trending-sidebar { display: none; }
      .trust-grid { grid-template-columns: repeat(2, 1fr); }
      .tools-grid { grid-template-columns: 1fr; }
      .programs-grid { grid-template-columns: repeat(2, 1fr); }
      .videos-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .header-top { padding: 12px 16px; }
      .logo { font-size: 22px; }
      .nav-list { overflow-x: auto; justify-content: flex-start; }
      .nav-item > button { padding: 12px 14px; font-size: 14px; }
      .mega-menu { position: fixed; left: 16px; right: 16px; transform: none; min-width: unset; }
      .hero-main { padding: 32px 24px; min-height: 280px; }
      .hero-title { font-size: 24px; }
      .reads-grid { grid-template-columns: 1fr; }
      .trust-grid { grid-template-columns: 1fr; }
      .programs-grid { grid-template-columns: 1fr; }
      .videos-grid { grid-template-columns: 1fr; }
      .drug-tools-grid { grid-template-columns: 1fr; }
      .newsletter-form { flex-direction: column; }
      .footer-newsletter-form { flex-direction: column; }
      .section-header { flex-direction: column; align-items: flex-start; gap: 12px; }
    }

    @media (max-width: 480px) {
      .container { padding: 0 16px; }
      .header-actions .sign-in-link { display: none; }
    }

    /* ============ UTILITY ============ */
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0,0,0,0);
      white-space: nowrap;
      border: 0;
    }
  </style>
